return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Spanish (Spain)','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:34+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'es_ES','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" guardado.','"%1$s" created. %2$d template updated.'=>'"%1$s" creado. %2$d plantilla actualizada.' . "\0" . '"%1$s" creado. %2$d plantillas actualizadas.','"%s" created.'=>'"%s" creado.','%d language not yet linked'=>'%d idioma aún no vinculado' . "\0" . '%d idiomas aún no vinculados','%d link updated.'=>'%d enlace actualizado.' . "\0" . '%d enlaces actualizados.','%d locale pack installed.'=>'%d paquete de idioma instalado.' . "\0" . '%d paquetes de idioma instalados.','%d navigation reference updated.'=>'Se actualizó %d referencia de navegación.' . "\0" . 'Se actualizaron %d referencias de navegación.','%d part reference updated.'=>'Se actualizó la referencia de %d parte.' . "\0" . 'Se actualizaron %d referencias de partes.','%s Archive'=>'Archivo de %s','(avg %.1f hits/block)'=>'(promedio %.1f hits/bloque)','(avg %.1f hits/entry)'=>'(promedio %.1f aciertos/entrada)','(disabled)'=>'(desactivado)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} no tenía enlaces reemplazables — re-escanea para investigar)','.txt file(s) in the directory'=>'.txt archivo(s) en el directorio','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d plantilla(s) localizada(s) del tema &#8220;%2$s&#8221; se conservan en la base de datos pero actualmente están inactivas. Volverán a activarse si vuelves a activar ese tema. Para transferir tus traducciones al nuevo tema, regénéralas a través de <strong>Configuración → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> enlace(s) corregible(s) automáticamente','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> enlace(s) que necesitan revisión manual','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> ruta(s) obsoleta(s)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> problema(s) de plantilla','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Solo acepta archivos .mo compilados. El nombre del archivo debe seguir el patrón {textdomain}-{locale}.mo. La carga de un archivo con el mismo nombre que uno existente lo reemplazará.','Action'=>'Acción','Actions'=>'Acciones','active'=>'activo','Active Languages'=>'Idiomas activos','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Idiomas activos: agrega cada idioma que deseas soportar. Cada idioma obtiene un prefijo de URL o subdominio y una etiqueta hreflang en la cabecera &lt;head&gt; de la página.','Active Provider'=>'Proveedor activo','Add entry'=>'Añadir entrada','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Agregar instrucciones para mejorar el borrador — por ejemplo, hacerlo más corto, agregar una sección de conclusión, usar un registro más formal, incluir un bloque de preguntas frecuentes…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Agrega instrucciones para mejorar el borrador — por ejemplo, hacerlo más corto, agregar una sección de conclusión, usar un registro más formal…','Add new entry'=>'Añadir nueva entrada','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Agregue un término por fila. Se requiere tanto el término fuente como la representación objetivo. El par de idiomas determina a qué trabajos de traducción se aplica la restricción.','Adds a link to the home page so visitors can browse in their language.'=>'Agrega un enlace a la página de inicio para que los visitantes puedan navegar en su idioma.','Administrators only (manage_options)'=>'Solo administradores (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Después de cambiar el idioma principal, actualiza los enlaces permanentes (sección a continuación) para que la enrutación de URL se actualice.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Después de cambiar la configuración de la estructura de URL (prefijo de ruta ↔ subdominio), visite siempre Configuración → Enlaces permanentes y haga clic en Guardar cambios para vaciar las reglas de reescritura.','AI Behaviour Preset'=>'Preajuste de comportamiento de IA','AI cache cleared. %d entry was removed.'=>'Caché de IA limpiada. Se eliminó %d entrada.' . "\0" . 'Caché de IA limpiada. Se eliminaron %d entradas.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'Caché de IA: lista las respuestas en caché de IA con conteos de aciertos. Limpie toda la caché o las entradas de una sola publicación. Use "Limpiar" antes de probar un cambio de traducción — los resultados en caché se devuelven incluso cuando cambia el preset o el modelo de IA hasta que se elimina la entrada de la caché.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Las funciones de IA son opcionales. El enrutamiento de idiomas, hreflang, el conmutador de idiomas y el sistema de grupos de traducción funcionan sin un proveedor configurado.','AI Limits & Security'=>'Límites y Seguridad de IA','AI provider returned an empty response.'=>'El proveedor de IA devolvió una respuesta vacía.','AI Usage'=>'Uso de IA','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Apunta a 120–160 caracteres. Déjalo vacío para usar el valor predeterminado del extracto.','All time'=>'Todo el tiempo','Allow editors to lock individual blocks'=>'Permitir a los editores bloquear bloques individuales','Allow Gutenberg template-editing mode on post screens'=>'Permitir modo de edición de plantilla de Gutenberg en pantallas de publicaciones','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'También elimina asignaciones de idioma, relaciones de traducción, meta descripciones, glosario y Memoria de Traducción cuando se desinstala el plugin.','Also generate meta description'=>'También generar meta descripción','Alternative (server-side):'=>'Alternativa (lado del servidor):','An unknown error occurred.'=>'Ocurrió un error desconocido.','and'=>'y','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'cualquiera','API calls saved by cache'=>'Llamadas API guardadas por caché','API Key'=>'Clave API','API Keys'=>'Claves API','API Keys Tab'=>'Pestaña de claves API','API Response Cache'=>'Caché de respuestas API','Applied ✓'=>'Aplicado ✓','Apply failed — please try again.'=>'La aplicación falló — por favor, intenta de nuevo.','Apply to Block'=>'Aplicar al bloque','Apply to Editor'=>'Aplicar al Editor','Apply to Footnote'=>'Aplicar a nota al pie','Apply to Meta Description'=>'Aplicar a la descripción meta','Apply translation'=>'Aplicar traducción','Applying…'=>'Aplicando…','Approximate size'=>'Tamaño aproximado','Archive'=>'Archivo','Archive: %s'=>'Archivo: %s','Authors and above (edit_published_posts)'=>'Autores y superiores (edit_published_posts)','Behavior'=>'Comportamiento','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Comportamiento: elija el preset de IA (Literal, Balanceado, Creativo), agregue instrucciones personalizadas en todo el sitio, habilite o deshabilite la traducción automática después de guardar la publicación y configure la Memoria de Traducción.','Block Content'=>'Contenido del bloque','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Muestra un aviso cortés cuando la página actual se muestra en su idioma fuente porque no existe una traducción para el idioma del visitante. Impulsado por la señal LINGUAFORGE_LANG_FALLBACK_ACTIVE del enrutador de Lingua Forge — no emite nada cuando existe una traducción para la configuración regional de la solicitud.','Block Editor'=>'Editor de bloques','block keywordfallback'=>'reemplazo','block keywordi18n'=>'i18n','block keywordlanguage'=>'idioma','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'traducción','Block locking'=>'Bloqueo de bloques','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Patrones de bloques registrados para tipos de publicaciones personalizadas. Usa el botón de traducir para producir una variante en otro idioma. El contenido traducido se guarda aquí y puede copiarse en cualquier publicación CPT desde el inserter de patrones del editor de bloques o usarse como punto de partida para un patrón sincronizado (Bloque reutilizable).','block titleMissing Translation Notice'=>'Aviso de traducción faltante','Block translation reuses'=>'Reutilizaciones de traducción de bloques','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Caché de traducción a nivel de bloque compartido entre publicaciones. Cuando está habilitado, bloques idénticos (mismo marcado, par de idiomas y glosario) se sirven desde la memoria en lugar de llamar a la IA nuevamente. Configure en Configuración → Comportamiento.','Browser language redirect'=>'Redirección por idioma del navegador','Built-in preset instructions:'=>'Instrucciones predefinidas incorporadas:','Bulletize (•-prefixed)'=>'Listar con viñetas (prefijo •)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Almacena en caché los equivalentes traducidos a nivel de bloque para que el contenido reutilizable (pie de página compartido, barras laterales, acordeones, secciones legales con mucho texto estándar) no tenga que hacer una llamada API cada vez. Cuando está habilitado, el flujo de traducción analiza cada publicación en bloques, busca cada bloque en la caché y envía solo los bloques no en caché a la IA en una solicitud agrupada. Las ediciones del glosario y los cambios en el preajuste de cumplimiento invalidan automáticamente las traducciones en caché afectadas. Ver estadísticas y limpiar la caché en Mantenimiento.','cached'=>'en caché','Cached API responses'=>'Respuestas API en caché','Cached block translations'=>'Traducciones de bloques en caché','Cancel'=>'Cancelar','Cannot determine target language from slug.'=>'No se puede determinar el idioma de destino a partir del slug.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limita cuánto puede generar la IA en el sitio y restringe qué roles de usuario pueden activar llamadas pagadas a la IA. Se superpone al límite de tasa por usuario (30 solicitudes / minuto, codificado en duro) que ya protege contra bucles descontrolados de un solo usuario.','chars'=>'caracteres','Chunk translated'=>'Fragmento traducido','Chunk translated to:'=>'Fragmento traducido a:','Clear'=>'Borrar','Clear All'=>'Borrar todo','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'¿Borrar todos los resultados en caché de IA? Las solicitudes futuras activarán llamadas API nuevas hasta que se reconstruya la caché.','Clear API Response Cache'=>'Borrar caché de respuestas API','Clear Debug Files'=>'Borrar archivos de depuración','Clear hints'=>'Borrar pistas','Clear input'=>'Borrar entrada','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'¿Borrar toda la Memoria de Traducción? Las traducciones futuras reconstruirán la caché a medida que se ejecuten.','Clear Translation Memory'=>'Borrar Memoria de Traducción','Close'=>'Cerrar','Close language panel'=>'Cerrar panel de idiomas','Close popover'=>'Cerrar ventana emergente','Compliance Preset'=>'Preajuste de cumplimiento','Content generated'=>'Contenido generado','Content Generator'=>'Generador de contenido','Content ready'=>'Contenido listo','Contributors and above — default (edit_posts)'=>'Colaboradores y superiores — predeterminado (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Controla cuánto contenido se envía a la IA y cuán grande puede ser la respuesta. Deja en blanco para usar el valor predeterminado incorporado (mostrado como marcador de posición). Aumenta estos valores si las páginas grandes se cortan; bájalos para reducir costos de API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controla el presupuesto de tokens y los límites de entrada para la función Generador de contenido de IA. Deja los campos en blanco para usar los valores predeterminados integrados.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controla qué sucede cuando un administrador elimina el plugin desde Plugins → Plugins instalados → Eliminar. La configuración del plugin y las cachés de AI siempre se eliminan. Las asignaciones de idioma y las relaciones de traducción se mantienen por defecto para que una desinstalación accidental o una reinstalación puedan continuar donde lo dejaron.','Conversational'=>'Conversacional','Copied ✓'=>'Copiado ✓','Copy'=>'Copiar','Copy markup'=>'Copiar marcado','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Copia el resultado y pégalo donde sea necesario (por ejemplo, directamente en el campo de notas al pie).','Copy to safe storage'=>'Copiar a almacenamiento seguro','Could not add entry: source term and target term are required.'=>'No se pudo añadir la entrada: se requieren el término fuente y el término destino.','Could not copy the file. Check that the uploads folder is writable.'=>'No se pudo copiar el archivo. Verifica que la carpeta de cargas tenga permisos de escritura.','Could not instantiate the provider.'=>'No se pudo instanciar el proveedor.','Could not save the file. Check that the uploads folder is writable.'=>'No se pudo guardar el archivo. Verifica que la carpeta de cargas tenga permisos de escritura.','Could not save the glossary entry.'=>'No se pudo guardar la entrada del glosario.','CPT Block Patterns'=>'Patrones de bloques CPT','Create'=>'Crear','Create missing'=>'Crear faltantes','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Crear traducciones para el tipo de publicación "%s" requiere una integración activa. Asegúrate de que la integración requerida esté instalada y activa.','Creating…'=>'Creando…','Creative / Marketing'=>'Creativo / Marketing','Creative / Marketing instructions'=>'Instrucciones creativas / de marketing','Current content (will be overwritten)'=>'Contenido actual (será sobrescrito)','Current title'=>'Título actual','Current: {current}'=>'Actual: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Actualmente heredado de la constante %s. Seleccionar un valor aquí lo sobrescribirá.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Actualmente se omite para publicaciones que usan marcadores de atributos de comentario de bloque (campos wp:details, resumen, etc.) — estos pasan a la ruta de traducción de llamada única existente.','Currently:'=>'Actualmente:','Custom'=>'Personalizado','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Cuota diaria de IA alcanzada (%1$d solicitudes). Se reinicia a las %2$s UTC.','Daily request limit'=>'Límite diario de solicitudes','Debug Files'=>'Archivos de depuración','Debug files cleared. %d file was removed.'=>'Archivos de depuración borrados. Se eliminó %d archivo.' . "\0" . 'Archivos de depuración borrados. Se eliminaron %d archivos.','Debug logging'=>'Depuración','Debug logging disabled.'=>'Registro de depuración deshabilitado.','Debug logging enabled.'=>'Registro de depuración habilitado.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Depuración: habilite el registro de depuración para capturar los prompts de IA y las respuestas de API en un archivo local. Desactive después de solucionar problemas — el modo de depuración escribe un archivo en cada solicitud de IA.','Delete'=>'Eliminar','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'¿Eliminar todos los archivos .txt en el directorio de depuración? El directorio en sí permanecerá para que futuras escrituras de depuración sigan llegando de manera limpia.','Delete all files for this override (both .mo and .po)?'=>'¿Eliminar todos los archivos de esta sobrescritura (tanto .mo como .po)?','Delete content data on uninstall'=>'Eliminar datos de contenido al desinstalar','Delete this glossary entry?'=>'¿Eliminar esta entrada del glosario?','Describe what to write — topic, key points, structure…'=>'Describe qué escribir — tema, puntos clave, estructura…','Directory'=>'Directorio','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Deshabilitar durante la afinación de prompts o cuando necesite que cada solicitud llegue al proveedor de IA. La desactivación no elimina las entradas en caché — volver a habilitar las restaura. Se espera que el aumento del gasto en API en sitios concurridos sea inmediato cuando está deshabilitado.','Display'=>'Mostrar','Displays the Lingua Forge language switcher.'=>'Muestra el selector de idioma de Lingua Forge.','Documentation'=>'Documentación','Done'=>'Hecho','Done — {done} of {total} post(s) fixed.'=>'Hecho — {done} de {total} publicaciones corregidas.','Down'=>'Abajo','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Descarga e instala un paquete de idioma de WordPress directamente desde WordPress.org. Una vez instalado, el idioma estará disponible para el enrutamiento de URL y el flujo de trabajo de traducción AI. La lista de idiomas disponibles se obtiene bajo demanda — haz clic en el botón de abajo para cargarla.','Dropdown direction'=>'Dirección del desplegable','Editors and above (edit_others_posts)'=>'Editores y superiores (edit_others_posts)','Enable API response caching'=>'Habilitar caché de respuestas API','Enable block-level translation cache reuse across posts'=>'Habilitar reutilización de caché de traducción a nivel de bloque en varias publicaciones','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Ingrese su clave API para al menos un proveedor de IA. Las claves están encriptadas en reposo usando AES-256-GCM con un secreto específico del sitio (LINGUAFORGE_SECRET). No comparta exportaciones de bases de datos sin rotar primero el secreto.','environment variable'=>'variable de entorno','Error'=>'Error','Expand'=>'Ampliar','Expected: {expected}'=>'Esperado: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Orientación adicional — tono, estilo, restricciones, público objetivo…','Extra guidance — tone, style, constraints…'=>'Orientación adicional — tono, estilo, restricciones…','Failed. Please try again.'=>'Fallido. Por favor, inténtalo de nuevo.','Feature'=>'Función','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Las funciones están agrupadas en dos niveles. Ingresa el identificador exacto del modelo para cada nivel y proveedor. Deja un campo en blanco para usar el valor predeterminado incorporado (mostrado como marcador de posición). Solo se llaman los modelos del proveedor activo en tiempo de ejecución — configura los otros con anticipación si planeas cambiar.','File copied to safe storage successfully.'=>'Archivo copiado a almacenamiento seguro con éxito.','Files'=>'Archivos','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Los archivos se almacenan en el directorio a continuación. Útil para diagnosticar problemas de traducción; desactívalo una vez que tengas lo que necesitas para que los archivos no se acumulen. También puedes forzar esto desde wp-config.php con `define( \'LINGUAFORGE_AI_DEBUG\', true );` que anula el interruptor.','Filter'=>'Filtro','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtra con linguaforge_debug_dir para redirigir la salida de depuración a una ubicación no pública.','Fix'=>'Corregir','Fix All'=>'Corregir todo','Fix all links'=>'Arreglar todos los enlaces','Fix all parts'=>'Arreglar todas las partes','Fix Links'=>'Corregir enlaces','Fix Nav'=>'Corregir navegación','Fix Parts'=>'Corregir partes','Fix Template'=>'Corregir plantilla','Fixing {n} / {total}…'=>'Corriendo {n} / {total}…','Fixing…'=>'Arreglando…','Flush Permalink Rules'=>'Actualizar reglas de enlaces permanentes','Flush Permalinks'=>'Actualizar enlaces permanentes','Footnote Content'=>'Contenido de la nota al pie','footnote(s) translated — applied together with content.'=>'Notas al pie traducidas — aplicadas junto con el contenido.','Footnotes'=>'Notas al pie','Footnotes payload (advanced)'=>'Carga útil de notas al pie (avanzado)','Forbidden'=>'Prohibido','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forzado DESACTIVADO por la constante LINGUAFORGE_AI_DEBUG en wp-config.php. Elimina esa línea para controlar este interruptor desde aquí.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forzado ACTIVADO por la constante LINGUAFORGE_AI_DEBUG en wp-config.php. Elimina esa línea para controlar este interruptor desde aquí.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Encontrados {parts} en <strong>{total}</strong> de <strong>{scanned}</strong> publicaciones escaneadas para <strong>{lang}</strong>.','From'=>'De','Front Page'=>'Página principal','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Localización FSE: estructura, traduzca y corrija enlaces en plantillas y partes de plantillas de Edición Completa del Sitio directamente desde esta pestaña.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Plantillas FSE sembradas desde el tema activo. Crea y personaliza en el Editor del sitio.','Full Article'=>'Artículo completo','Full post'=>'Publicación completa','General'=>'General','Generate'=>'Generar','Generate Content'=>'Generar contenido','Generate content…'=>'Generar contenido…','Generate Excerpt'=>'Generar extracto','Generate Meta Description'=>'Generar meta descripción','Generated Content'=>'Contenido generado','Generated meta description'=>'Meta descripción generada','Generating…'=>'Generando…','Generation failed.'=>'La generación falló.','Getting started'=>'Comenzando','Global AI preset'=>'Preajuste global de IA','Global default (%s)'=>'Predeterminado global (%s)','Glossary'=>'Glosario','Glossary entry added.'=>'Entrada del glosario añadida.','Glossary entry removed.'=>'Entrada del glosario eliminada.','Glossary Tab'=>'Pestaña de Glosario','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Ocultar','Hints'=>'Pistas','Home link text'=>'Texto del enlace a inicio','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Cómo debe aparecer en la traducción. Escribe el mismo valor que el término fuente para indicar a la IA que lo conserve exactamente.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Icono + etiqueta','Icon only'=>'Solo icono','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Si se marca, desinstalar el plugin eliminará permanentemente todas las asignaciones de idioma, relaciones de traducción, meta descripciones, preajustes por página, el glosario de AI y la Memoria de Traducción para cada publicación en este sitio. Esto no se puede deshacer. No marque esta opción a menos que esté eliminando completamente el soporte multilingüe del sitio.','Improve writing'=>'Mejorar escritura','Informative'=>'Informativo','Input tokens'=>'Tokens de entrada','Install'=>'Instalar','Install a Language'=>'Instalar un idioma','Installing…'=>'Instalando…','Instructions (optional)'=>'Instrucciones (opcional)','Instructions / key points'=>'Instrucciones / puntos clave','Integration API'=>'API de integración','Internal Link Fixer'=>'Arreglador de enlaces internos','Introduction only'=>'Solo introducción','Invalid file reference.'=>'Referencia de archivo inválida.','Invalid filename.'=>'Nombre de archivo inválido.','Invalid language.'=>'Idioma no válido.','Invalid locale code.'=>'Código de idioma no válido.','Invalid or primary language.'=>'Idioma inválido o principal.','Invalid post type.'=>'Tipo de publicación no válido.','Invalid template part.'=>'Parte de plantilla no válida.','Invalid template type.'=>'Tipo de plantilla no válido.','Key points, ideas, or structure to build from…'=>'Puntos clave, ideas o estructura sobre la que construir…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Las claves se cifran con AES-256-CBC antes de almacenarlas en la base de datos de WordPress. El secreto de cifrado se deriva de tus sales de autenticación de WordPress (wp-config.php), por lo que las claves en texto plano nunca llegan a la base de datos.','Language'=>'Idioma','Language %s installed successfully.'=>'El idioma %s se instaló correctamente.','Language (optional)'=>'Idioma (opcional)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'La instalación de idiomas está deshabilitada en este servidor (DISALLOW_FILE_MODS está activado).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'La instalación de idiomas está deshabilitada en este servidor. La constante DISALLOW_FILE_MODS está configurada en wp-config.php. Instala manualmente los paquetes de idioma mediante WP-CLI: wp language core install de_DE','Language label'=>'Etiqueta del idioma','Language Overrides'=>'Sobrescrituras de idioma','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Sobrescrituras de idioma: gestione archivos de sobrescritura personalizados .po/.mo para las cadenas de la interfaz de usuario de Lingua Forge. Use esto en lugar de editar archivos del plugin directamente — las sobrescrituras sobreviven a las actualizaciones.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'La instalación del paquete de idioma falló. El idioma puede ya estar instalado, el código de idioma puede ser incorrecto, o tu servidor puede bloquear las escrituras en archivos.','Language Setup'=>'Configuración de idioma','Language Switcher'=>'Selector de idioma','Language switcher'=>'Conmutador de idiomas','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Copias específicas del idioma de las partes de plantilla del tema. Una vez estructuradas, las plantillas se actualizan para hacer referencia a la parte específica del idioma.','Language:'=>'Idioma:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Idiomas actualmente conocidos por el enrutador (derivados de los paquetes de idioma de WordPress instalados más el idioma principal). Instala paquetes de idioma adicionales en la sección inferior para hacer más idiomas disponibles para el enrutamiento y la traducción.','Last 30 days'=>'Últimos 30 días','Last 7 days'=>'Últimos 7 días','Lead paragraph (≤60 w)'=>'Párrafo principal (≤60 palabras)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Deje en blanco un campo de modelo para usar el predeterminado incorporado para ese nivel. El texto del marcador de posición muestra qué modelo se usará.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Deja en blanco para nombres de marcas y términos independientes del idioma que deben mantenerse sin importar desde qué idioma se traduzca.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Deja en blanco para aplicar esta entrada a todos los idiomas destino — ideal para nombres de marcas, abreviaturas y términos que deben mantenerse exactamente en cada traducción.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Deja en blanco para mantener la clave existente. Ingresa un nuevo valor para reemplazarla.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Deja en blanco para usar el valor predeterminado incorporado. Borrar una anulación guardada restaura el valor predeterminado en el próximo guardado.','Legal / Compliance'=>'Legal / Cumplimiento','Legal / Compliance instructions'=>'Instrucciones legales / de cumplimiento','Light'=>'Ligero','Light (default — fast and cost-effective)'=>'Ligero (predeterminado — rápido y rentable)','Light (fast and cost-effective — Haiku / Flash)'=>'Ligero (rápido y rentable — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Ligero: utilizado para descripciones meta y generación de extractos — rápido, de bajo costo.','Limit results to pages in the given Lingua Forge language code.'=>'Limitar resultados a páginas en el código de idioma de Lingua Forge dado.','Limits'=>'Límites','Lingua Forge'=>'Lengua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge agrega enrutamiento multilingüe, traducción impulsada por IA, etiquetas hreflang SEO y un conmutador de idiomas a su sitio WordPress.','Lingua Forge AI Tools'=>'Herramientas de IA de Lingua Forge','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge restringe por defecto dos funciones de Gutenberg para mantener la coherencia editorial en todos los idiomas. Participa aquí si necesitas capacidades completas de Gutenberg / FSE.','Lingua Forge Settings'=>'Configuraciones de Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge usa dos capas de caché independientes para evitar llamadas redundantes a la API de IA. Use las pestañas a continuación para inspeccionar y gestionar cada una.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge usa dos niveles de modelos por proveedor:','Lingua Forge — Quick Translate'=>'Lengua Forge — Traducción rápida','Lingua Forge — Settings'=>'Lingua Forge — Configuraciones','link(s)'=>'enlace(s)','Links'=>'Enlaces','Load available languages'=>'Cargar idiomas disponibles','Loading…'=>'Cargando…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate almacena sus traducciones personalizadas en wp-content/languages/loco/ — una ubicación que puede ser borrada silenciosamente por una actualización del núcleo de WP, reinstalación del plugin, o si Loco Translate se elimina. Copiar archivos aquí los mueve al directorio Lingua Forge i18n-overrides, que persiste a través de todos esos eventos y se carga automáticamente en cada solicitud.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copiar a Almacenamiento Seguro','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Capacidad de WordPress más baja permitida para activar funciones de IA. Restringir esto en sitios con múltiples autores evita que Colaboradores o cuentas de prueba ejecuten llamadas pagadas a la IA. Sobrescribe por función mediante el filtro linguaforge_required_capability.','Maintenance'=>'Mantenimiento','Maintenance Tab'=>'Pestaña de mantenimiento','Make casual'=>'Hacer informal','Make concise'=>'Hacer conciso','Make formal'=>'Hacer formal','Mark citations needed'=>'Marcar citas necesarias','Max context characters'=>'Máx. caracteres de contexto','Max hints characters'=>'Máx. caracteres de pistas','Max input characters'=>'Caracteres máximos de entrada','Max output tokens'=>'Tokens máximos de salida','Maximum characters accepted from the input field. Default: 8 000.'=>'Número máximo de caracteres aceptados desde el campo de entrada. Predeterminado: 8 000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Número máximo de caracteres del contenido de la publicación existente pasado a la IA como contexto semilla cuando no se proporcionan Pistas. Predeterminado: 6 000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Número máximo de caracteres leídos del campo de Pistas. Predeterminado: 2 000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Número máximo de caracteres del contenido de la publicación enviado a la IA. 0 significa sin límite — siempre se envía el contenido completo (recomendado). Establece un valor distinto de cero solo si tu proveedor tiene una ventana de contexto ajustada. Se escribe una advertencia en el registro de errores de PHP cada vez que se recorta el contenido.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Número máximo de tokens que la IA puede producir en una sola respuesta de traducción. Si una traducción se corta silenciosamente al final, aumenta este valor. Predeterminado: 16,000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Número máximo de tokens que la IA puede producir por ejecución de generación. Aumenta esto si se cortan artículos completos. Predeterminado: 8 192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Número máximo de tokens que la IA puede producir por traducción rápida. Predeterminado: 2 000.','Meta Description'=>'Meta descripción','Meta Description, Excerpt Generator'=>'Meta Descripción, Generador de extractos','Minimum role'=>'Rol mínimo','Missing pattern name or language.'=>'Falta el nombre del patrón o el idioma.','Mode'=>'Modo','Model'=>'Modelo','Model tier'=>'Nivel del modelo','Models'=>'Modelos','Models Tab (General)'=>'Pestaña de modelos (General)','Most recent cached block'=>'Bloque en caché más reciente','Most recent cached response'=>'Respuesta en caché más reciente','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Enrutamiento multilingüe, etiquetas meta SEO y herramientas de contenido AI para WordPress. Combina detección de idioma, enrutamiento de URL, hreflang, descripciones meta y funciones de extracto, meta y traducción impulsadas por IA.','Name displayed in this language. Leave empty to use the source name.'=>'Nombre mostrado en este idioma. Deja en blanco para usar el nombre original.','Navigation'=>'Navegación','Navigation has no content to translate.'=>'La navegación no tiene contenido para traducir.','Navigation not found.'=>'Navegación no encontrada.','Navigation posts are translated via the Router tab, not this button.'=>'Las publicaciones de navegación se traducen a través de la pestaña Router, no con este botón.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'La traducción de navegación requiere un proveedor de IA activo. Configura una clave API en la pestaña de Claves API.','Navigations'=>'Navegaciones','Network error — could not reach the WordPress AJAX endpoint.'=>'Error de red — no se pudo acceder al endpoint AJAX de WordPress.','No %s version found in this translation group.'=>'No se encontró ninguna versión de %s en este grupo de traducciones.','No AI provider configured.'=>'No se ha configurado ningún proveedor de IA.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'No se ha registrado uso de IA en la ventana seleccionada (%s). Elige un rango más amplio arriba.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Aún no se ha registrado uso de IA. Una vez que un editor realice una traducción, genere una meta descripción o utilice cualquier otra función de IA, los totales aparecerán aquí.','No API key configured for this provider.'=>'No hay una clave API configurada para este proveedor.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'No hay instrucciones predefinidas — cada función de IA usa sus propios valores predeterminados ajustados. Completa el campo de instrucciones de aviso personalizado a continuación para agregar tus propias reglas para todo el sitio.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Aún no se encuentran archivos personalizados de Loco Translate. Aparecen aquí una vez que guardas una traducción en Loco Translate.','No file was selected.'=>'No se seleccionó ningún archivo.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'No hay entradas en el glosario que coincidan con el filtro actual. Limpia el filtro para ver todas las entradas, o añade una nueva abajo.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Aún no hay entradas en el glosario. Añade una abajo para empezar a aplicar la terminología en las traducciones.','No internal links found to update.'=>'No se encontraron enlaces internos para actualizar.','No language-specific template parts found to map.'=>'No se encontraron partes de plantilla específicas del idioma para mapear.','No navigation references needed updating.'=>'No se necesitan actualizar referencias de navegación.','No override files uploaded yet.'=>'Aún no se han cargado archivos de sobrescritura.','No response from provider — check the error log for details.'=>'No hay respuesta del proveedor — revisa el registro de errores para más detalles.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'No hay idiomas secundarios configurados. Instala un paquete de idioma arriba para habilitar la estructura de plantillas.','No source content found to translate.'=>'No se encontró contenido fuente para traducir.','No source page linked yet.'=>'Aún no hay página fuente vinculada.','No template part references needed updating.'=>'No se necesitan actualizar referencias de partes de plantilla.','No {lang} translation registered (TRID missing)'=>'No hay traducción en {lang} registrada (TRID faltante)','Notes'=>'Notas','Notice message'=>'Mensaje de aviso','Notice settings'=>'Configuración de aviso','Oldest cached block'=>'Bloque en caché más antiguo','Oldest cached response'=>'Respuesta en caché más antigua','Only .mo files are accepted.'=>'Solo se aceptan archivos .mo.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Contexto opcional para editores (por ejemplo, "ASIC = Circuito Integrado de Aplicación Específica; conservar en inglés en contextos técnicos").','Output'=>'Salida','Output tokens'=>'Tokens de salida','overridden'=>'sobrescrito','Override file deleted.'=>'Archivo de sobrescritura eliminado.','Override file uploaded successfully.'=>'Archivo de sobrescritura cargado con éxito.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Sobrescribe el preajuste de IA para Traducción y Generación de contenido en esta página. Todas las demás funciones siempre usan el preajuste global.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Sobrescribe el preajuste de IA para Traducción y Generación de contenido en esta página. Las instrucciones personalizadas a nivel de sitio (Configuración → Comportamiento) siempre se añaden a cada solicitud independientemente de esta selección.','Overview'=>'Resumen','Page'=>'Página','Part'=>'Parte','Paste a footnote, sentence, or any snippet here…'=>'Pega una nota al pie, oración o cualquier fragmento aquí…','Paste text, or select text in the editor first…'=>'Pega el texto, o selecciona primero el texto en el editor…','Paste text, or select text on the page first…'=>'Pega el texto, o selecciona primero el texto en la página…','Paste your API key…'=>'Pega tu clave API…','Path prefix — example.com/de/'=>'Prefijo de ruta — ejemplo.com/de/','Pattern'=>'Patrón','Pattern has no content to translate.'=>'El patrón no tiene contenido para traducir.','Pattern not found.'=>'Patrón no encontrado.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patrón traducido y guardado. Copie el contenido en su publicación CPT mediante el inserto de patrones del editor de bloques o utilícelo como punto de partida para un bloque reutilizable.','Pattern translation failed.'=>'Fallo en la traducción del patrón.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'Caché por publicación para traducciones generadas por IA, descripciones meta, extractos y contenido. Siempre activo — no se requiere un interruptor separado. Las entradas se invalidan automáticamente cuando cambia el contenido o el proveedor/modelo de IA. Use el botón "↺ Re- traducir" de la barra de herramientas o haga clic en Limpiar abajo para forzar una llamada API nueva.','Permalink rules flushed successfully.'=>'Reglas de enlaces permanentes eliminadas con éxito.','Permission denied.'=>'Permiso denegado.','Persuasive'=>'Persuasivo','PHP constant'=>'constante de PHP','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Fije términos que no deben traducirse o que siempre deben mostrarse de una manera específica (por ejemplo, nombres de marcas, nombres de productos, acrónimos). Las restricciones del glosario se inyectan en cada solicitud de traducción de IA para todas las funciones: traducción de publicaciones, descripción meta, extracto y traducción de plantillas FSE.','Plain language'=>'Lenguaje sencillo','Please enter some instructions first…'=>'Por favor, ingresa algunas instrucciones primero…','Please enter some text first…'=>'Por favor, ingresa algún texto primero…','Post'=>'Publicación','Post not found.'=>'Publicación no encontrada.','Post Types'=>'Tipos de publicaciones','Prefilled from excerpt. Edit to override.'=>'Prellenado desde extracto. Edita para sobrescribir.','Primary Language'=>'Idioma principal','Primary language'=>'Idioma principal','Primary language saved.'=>'Idioma principal guardado.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Idioma principal: el idioma en el que está escrito su contenido existente. Todas las traducciones se producen desde este idioma; cambiarlo no mueve ni elimina publicaciones.','Processing…'=>'Procesando…','Provider'=>'Proveedor','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'El proveedor no devolvió texto. Revisa el registro de errores de WordPress para conocer la razón detallada del fallo.','Quality'=>'Calidad','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Calidad (predeterminado — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Calidad (Soneto / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Calidad: utilizado para la traducción de publicaciones y generación de contenido — mayor calidad, mayor costo.','Quick Translate'=>' Traducción rápida','Quick Translation'=>' Traducción rápida','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'La traducción rápida se usa en modo fragmento/pedazo — pasajes cortos traducidos a demanda desde la barra de herramientas, editor o popovers de bloques. Utiliza una configuración separada y más ligera que la traducción de página completa para mantener las respuestas rápidas y rentables.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Vuelve a habilitar canLockBlocks de Gutenberg. Útil para plantillas editoriales que necesitan evitar que los colaboradores muevan o eliminen bloques específicos.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Vuelve a habilitar supportsTemplateMode. Esencial en flujos de trabajo de Edición Completa del Sitio donde las anulaciones de plantilla a nivel de publicación son intencionales.','Re-generates and updates the cached result.'=>'Regenara y actualiza el resultado en caché.','Re-scan'=>'Reescanear','Re-scanning…'=>'Re-escaneando…','Re-translate'=>'Re-traducir','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Redirige a los visitantes a su idioma preferido según la cabecera Accept-Language del navegador','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Refina aún más — por ejemplo, "hazlo más corto" o "usa un tono formal"…','Refine further:'=>'Refinar más:','Refinement'=>'Refinamiento','Refinement failed — please try again.'=>'La refinación falló — por favor, intenta de nuevo.','Refining…'=>'Refinando…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenera las reglas de reescritura de WordPress para que los prefijos de URL, los slugs específicos del idioma y las reescrituras de archivos estén sincronizados. Es necesario después de cambiar el idioma principal o agregar soporte para nuevos idiomas.','Remove stored key'=>'Eliminar clave almacenada','Report an issue on GitHub'=>'Reportar un problema en GitHub','Request failed — please try again.'=>'La solicitud falló — por favor, intenta de nuevo.','Request failed.'=>'La solicitud falló.','Request failed. Check your connection.'=>'La solicitud falló. Verifica tu conexión.','Request failed. Please try again.'=>'La solicitud falló. Por favor, inténtalo de nuevo.','Requests'=>'Solicitudes','Reset'=>'Restablecer','Result will appear here…'=>'El resultado aparecerá aquí…','Retranslate'=>'Retraducir','Retranslating…'=>'Retraduciendo…','Review carefully — links and slugs not updated.'=>'Revisa cuidadosamente — enlaces y slugs no actualizados.','Review translation before applying'=>'Revisa la traducción antes de aplicar','Revise'=>'Revisar','Revision'=>'Revisión','Revision Type'=>'Tipo de revisión','Router'=>'Enrutador','Router Tab'=>'Pestaña de enrutador','Save Debug Setting'=>'Guardar configuración de depuración','Save Router Settings'=>'Guardar configuración del enrutador','Save Settings'=>'Guardar configuraciones','Save the post to persist changes.'=>'Guarda la publicación para mantener los cambios.','Save Uninstall Setting'=>'Guardar configuración de desinstalación','Saved to the meta description field when you apply.'=>'Guardado en el campo de meta descripción al aplicar.','Scan failed: '=>'Escaneo fallido: ','Scan request failed. Please try again.'=>'La solicitud de escaneo falló. Por favor, intenta de nuevo.','Scanning posts for broken language links…'=>'Escaneando publicaciones en busca de enlaces rotos de idiomas…','Search'=>'Buscar','Search Results'=>'Resultados de búsqueda','Security check failed — file path is not permitted.'=>'Error de seguridad — ruta del archivo no permitida.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Selecciona un idioma para gestionar sus plantillas FSE, partes de plantilla y menús de navegación.','Select language'=>'Seleccionar idioma','SEO character-count info'=>'Información de conteo de caracteres para SEO','Server setup (subdomain)'=>'Configuración del servidor (subdominio)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Establece el comportamiento predeterminado de IA para todas las funciones en todo el sitio. Las publicaciones individuales pueden sobrescribir esto para Traducción y Generación de Contenido a través del cuadro meta de Lingua Forge.','Settings'=>'Configuraciones','Settings saved.'=>'Configuraciones guardadas.','Show home link'=>'Mostrar enlace a inicio','Shown when no translation exists for the visitor\'s language.'=>'Mostrado cuando no existe una traducción para el idioma del visitante.','Single'=>'Individual','Single %s'=>'Individual %s','Single: %s'=>'Individual: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Techo en toda la web para solicitudes de IA por día UTC (cuenta tanto las traducciones en la barra de herramientas como las revisiones de bloques). El contador se reinicia a la medianoche UTC. Pon en 0 para desactivar el límite.','Size'=>'Tamaño','Some link fixes failed.'=>'Algunos arreglos de enlaces fallaron.','Some nav ref fixes failed.'=>'Algunas referencias de navegación no pudieron ser arregladas.','Some part fixes failed.'=>'Algunos arreglos de partes fallaron.','Some parts could not be created.'=>'Algunas partes no pudieron ser creadas.','Some templates could not be created.'=>'Algunas plantillas no pudieron ser creadas.','Some translations failed.'=>'Algunas traducciones fallaron.','Source file not found.'=>'Archivo fuente no encontrado.','Source lang'=>'Idioma fuente','Source language'=>'Idioma fuente','Source term'=>'Término fuente','Standard'=>'Estándar','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'El modo estándar usa la temperatura ajustada de cada función: Traducción T=0.2 (preciso), Traducción rápida T=0.4, Generador de contenido T=0.6 (creativo). Los otros preajustes aplican una temperatura fija en todas las funciones.','Status'=>'Estado','Status / Actions'=>'Estado / Acciones','Storytelling'=>'Narración','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Modo de preservación estricta para contenido legal, regulatorio, médico o técnico. Cuando está activado, cada función de IA usa una temperatura de muestreo baja y añade el apéndice abajo a su prompt del sistema — la terminología, números de artículos, unidades, nombres de marcas y lenguaje regulatorio se preservan exactamente en lugar de parafrasear.','Structured Outline'=>'Esquema estructurado','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'El modo de subdominio requiere que tu servidor web apunte todos los subdominios de idioma (por ejemplo, de.ejemplo.com) a esta instalación de WordPress. Después de cambiar de modo, actualiza las reglas de enlaces permanentes y borra cualquier caché. Si la URL de inicio incluye www (por ejemplo, www.ejemplo.com), usa el filtro lf_base_domain para establecer el dominio raíz sin www para que los subdominios se construyan correctamente.','Subdomain — de.example.com/'=>'Subdominio — de.ejemplo.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Proveedores compatibles: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Solo un proveedor está activo a la vez. Seleccione el proveedor activo en la pestaña General.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, por función','Target lang'=>'Idioma destino','Target Language'=>'Idioma de destino','Target language'=>'Idioma destino','Target term'=>'Término destino','Target: 140–160 chars for optimal SERP display'=>'Objetivo: 140–160 caracteres para una visualización óptima en SERP','Technical'=>'Técnico','Technical / Scientific'=>'Técnico / Científico','Technical / Scientific instructions'=>'Instrucciones técnicas / científicas','Template "%s" already exists.'=>'La plantilla "%s" ya existe.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'La plantilla "{expected}" no existe — créala primero en el Editor del Sitio.','Template has no content.'=>'La plantilla no tiene contenido.','Template mode'=>'Modo de plantilla','Template not found or not stored in the database.'=>'Plantilla no encontrada o no almacenada en la base de datos.','Template part "%s" already exists.'=>'La parte de plantilla "%s" ya existe.','Template part has no content.'=>'La parte de la plantilla no tiene contenido.','Template part not found or not stored in the database.'=>'Parte de plantilla no encontrada o no almacenada en la base de datos.','Template Parts'=>'Partes de plantilla','Templates'=>'Plantillas','Test connection'=>'Probar conexión','Testing…'=>'Probando…','Text domain / locale'=>'Dominio de texto / local','Text to translate'=>'Texto a traducir','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'La caché de respuestas API almacena el resultado bruto de cada solicitud de IA — traducción, descripción meta, extracto y generación de contenido — identificada por un hash de las entradas (contenido, par de idiomas, proveedor, modelo). Las solicitudes posteriores con entradas idénticas se sirven desde la caché sin llamada API. La caché es diferente de la Memoria de Traducción: la Memoria de Traducción opera a nivel de bloque y se comparte entre publicaciones; la caché de respuestas API opera a nivel de función y se identifica por publicación.','The editor did not accept the content — please try again.'=>'El editor no aceptó el contenido — por favor, intenta de nuevo.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'El nivel Ligero usa el modelo rápido configurado en la tabla de Modelos arriba (predeterminado: Haiku / Flash). Cambia a Calidad si necesitas la misma precisión de traducción que en modo de página completa para fragmentos.','The phrase as it appears in the source text.'=>'La frase tal como aparece en el texto fuente.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'El idioma principal siempre se sirve en la raíz de su sitio: sin prefijo en la URL en modo de ruta, sin subdominio de idioma en modo de subdominio. Todos los demás idiomas usan un prefijo de ruta /lang/ (por ejemplo, example.com/de/) o un subdominio de idioma (por ejemplo, de.ejemplo.com), dependiendo de la configuración de estructura de URL a continuación.','The source page has no footnotes.'=>'La página fuente no tiene notas al pie.','The upload failed — please try again.'=>'La carga falló — por favor, inténtalo de nuevo.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Estas notas al pie provienen de la página fuente y se muestran aquí solo para referencia. Agrégalas a esta página usando el editor de bloques.','This is the source page. Footnotes are edited directly in the block editor.'=>'Esta es la página fuente. Las notas al pie se editan directamente en el editor de bloques.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Esta clave actualmente la proporciona un servidor %s y no puede ser eliminada aquí. Ingresa una nueva clave arriba para sobrescribirla con un valor de la base de datos.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Consejo: para restablecer un modelo al valor predeterminado incorporado, borra el campo y guarda.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Para usar un secreto de cifrado personalizado (en lugar del valor derivado wp_salt), añade esto a wp-config.php:','Today'=>'Hoy','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'El consumo de tokens se agrupa por función, proveedor y modelo. Se registra en cada llamada exitosa a la IA; los pings de prueba de conexión se excluyen deliberadamente para no distorsionar los totales. La tabla subyacente agrega diariamente — selecciona una ventana a continuación para verla.','Tone'=>'Tono','tone'=>'tono','Tone:'=>'Tono:','Too many AI requests. Please retry in %d seconds.'=>'Demasiadas solicitudes de IA. Por favor, intenta de nuevo en %d segundos.','Total'=>'Total','Total tokens'=>'Tokens totales','Translate'=>'Traducir','Translate / Revise'=>'Traducir / Revisar','Translate / Revise block'=>'Traducir / Revisar bloque','Translate all'=>'Traducir todo','Translate chunk'=>'Traducir fragmento','Translate Content'=>'Traducir contenido','Translate missing'=>'Falta traducción','Translate page…'=>'Traducir página…','Translated content'=>'Contenido traducido','Translated Names'=>'Nombres traducidos','Translated title'=>'Título traducido','Translated to:'=>'Traducido a:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Traducido. Revisa en el Editor del Sitio — los enlaces internos, URLs de navegación y slugs de plantillas no se actualizan automáticamente.','Translating…'=>'Traduciendo…','Translation'=>'Traducción','Translation Caching'=>'Caché de traducción','Translation found but permalink could not be generated'=>'Se encontró la traducción pero no se pudo generar el enlace permanente','Translation Limits'=>'Límites de Traducción','Translation Limits & Behavior'=>'Límites y comportamiento de la traducción','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Límites de traducción: controla qué roles de usuario pueden activar la traducción por IA y establece un presupuesto mensual de tokens. Superar el presupuesto suspende las llamadas a la IA hasta que se reinicie el mes.','Translation Memory'=>'Memoria de traducción','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'La memoria de traducción almacena en caché los resultados de la IA por hash de contenido, par de idiomas, proveedor y modelo. La edición de una publicación invalida la entrada de la caché para que la próxima llamada de traducción obtenga un resultado nuevo.','Translation Memory cleared. %d cached block was removed.'=>'Memoria de traducción borrada. Se eliminó %d bloque en caché.' . "\0" . 'Memoria de traducción borrada. Se eliminaron %d bloques en caché.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Memoria de traducción: almacena la publicación traducida completa por hash de contenido. Límpiala cuando quieras forzar una retraducción de todas las publicaciones, independientemente de si su contenido cambió.','Translation workflow'=>'Flujo de trabajo de traducción','Translation, Content Generator'=>'Traducción, Generador de contenido','Type'=>'Tipo','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'Desinstalar comportamiento','Uninstall setting saved.'=>'Configuración de desinstalación guardada.','unknown error'=>'error desconocido','Unknown provider.'=>'Proveedor desconocido.','Up'=>'Arriba','Upload .mo file'=>'Cargar archivo .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Carga archivos .mo compilados para sobrescribir cadenas de plugins de terceros para locales específicos — por ejemplo, una traducción personalizada de VikBooking que use "apartamento" en lugar de "habitación". Los archivos deben seguir la convención de nombres de WordPress: {textdomain}-{locale}.mo (ej. vikbooking-ca.mo). Se almacenan en la carpeta de cargas y sobreviven a actualizaciones del plugin.','Upload Override'=>'Cargar Sobrescritura','URL could not be mapped to a post — check the link target exists'=>'La URL no pudo ser mapeada a una publicación — verifica que el destino del enlace exista','URL structure'=>'Estructura de URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Estructura de URL: modo prefijo de ruta (example.com/de/) no requiere cambios en el servidor. El modo subdominio (de.example.com) requiere un registro DNS comodín, un certificado SSL comodín y un cambio en la configuración del servidor web — consulta la guía de configuración del servidor.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Utiliza las pestañas en la parte superior de esta página para configurar cada área. Los cambios en la pestaña del enrutador tienen efecto inmediato; los cambios en las claves de IA y configuraciones del modelo se aplican a la próxima solicitud de IA.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tabla de terminología gestionada por el usuario por par de idiomas. Las entradas se añaden al prompt del sistema de traducción para que la IA utilice términos preferidos de manera consistente — fundamental para vocabulario de dominio ("kWp", "PPA", "punto de interconexión"), nombres de marcas que no deben traducirse y frases regulatorias estandarizadas. Ambos campos de idioma son opcionales: deja en blanco "Idioma fuente" para aplicar la entrada independientemente del idioma desde el que estás traduciendo; deja en blanco "Idioma destino" para aplicarlo a todos los idiomas destino a la vez.','Using custom meta description.'=>'Usando meta descripción personalizada.','View'=>'Ver','View built-in default'=>'Ver valor predeterminado incorporado','View details'=>'Ver detalles','View Lingua Forge details'=>'Ver detalles de Lingua Forge','Visit plugin site'=>'Visitar sitio del plugin','Warning:'=>'Advertencia:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Cuando la depuración de registros está habilitada (a través del interruptor a continuación o definiendo LINGUAFORGE_AI_DEBUG en wp-config.php), las funciones de traducción y traducción de plantillas FSE escriben sus solicitudes y respuestas de AI en disco para solucionar problemas. Usa esta sección para monitorear esa salida y borrarla una vez que tengas lo que necesitas; los archivos pueden crecer rápidamente en páginas grandes. Configura el directorio de destino a través del filtro linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Cuando está habilitado, los visitantes que visitan por primera vez sin cookie de idioma y sin prefijo de idioma en la URL son redirigidos a la versión en el idioma más cercano. La redirección se omite si el idioma preferido del navegador no está entre los idiomas activos del enrutador. Una vez que un visitante selecciona un idioma mediante el selector, la cookie tiene prioridad y se ignora la cabecera del navegador en futuras visitas.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Qué nivel de modelo usar para traducción de página completa. La calidad usa el modelo configurado en la tabla de Modelos arriba y se recomienda para traducciones precisas y de formato largo. Cambia a Ligero solo si la velocidad o el costo son prioritarios y el contenido es corto.','WP-CLI reference'=>'Referencia de WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Escribir solicitudes y respuestas de AI en disco para solucionar problemas','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'También puedes definir claves como constantes o variables de entorno (por ejemplo, en wp-config.php). Esas fuentes se usan automáticamente como respaldo cuando no se almacena una clave en la base de datos.','You do not have permission to manage these settings.'=>'No tienes permiso para gestionar estas configuraciones.','You do not have permission to read this post.'=>'No tienes permiso para leer esta publicación.','{n} stale path(s)'=>'{n} ruta(s) obsoleta(s)','— Any source language —'=>'— Cualquier idioma fuente —','— Any target language —'=>'— Cualquier idioma destino —','— Any target —'=>'— Cualquier destino —','— Any —'=>'— Cualquiera —','— auto-detect —'=>'— detección automática —','— select a language —'=>'— selecciona un idioma —','— toggle in Settings → Behavior.'=>'— interruptor en Actividades → Comportamiento.','← Back'=>'← Atrás','↑ Detected from current post'=>'↑ Detectado del publicación actual','↺ Re-translate'=>'↺ Re-traducir','↺ Refine'=>'↺ Refinar','↺ Refresh'=>'↺ Actualizar','↺ Refreshing…'=>'↺ Actualizando…','⚠ Borderline'=>'⚠ Limite','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ No se encontraron publicaciones <strong>{lang}</strong>. Asegúrate de que todas las publicaciones traducidas tengan su metadato de idioma establecido en <strong>{lang}</strong> en la caja de metadatos de idioma.','⚠ No changes'=>'⚠ Sin cambios','⚠ No changes — re-scan?'=>'⚠ Sin cambios — ¿re-escaneo?','✅ Fixed ({n})'=>'✅ Corregido ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ No se encontraron enlaces rotos ni incompatibilidades de plantilla para <strong>{lang}</strong>. Se escanearon <strong>{scanned}</strong> publicación(es) y página(s) — todas las verificaciones pasaron. Los enlaces de partes de plantilla (cabecera, pie de página, barra lateral) no se incluyen aquí — usa el botón Corregir partes de plantilla para verificar esas por separado.','✅ Template fixed'=>'✅ Plantilla corregida','✓ All parts created.'=>'✓ Todas las partes creadas.','✓ All templates created.'=>'✓ Todas las plantillas creadas.','✓ All translated.'=>'✓ Todo traducido.','✓ Configured'=>'Configurado ✓','✓ Connection OK'=>'✓ Conexión OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Contenido generado — mira la superposición para revisar, refinar y aplicar.','✓ Done'=>'✓ Hecho','✓ Enabled'=>'✓ Activado','✓ Good length'=>'✓ Buena longitud','✓ In safe storage'=>'✓ En almacenamiento seguro','✓ Language installed.'=>'✓ Idioma instalado.','✓ Links fixed.'=>'✓ Enlaces arreglados.','✓ Nav refs fixed.'=>'✓ Referencias de navegación arregladas.','✓ Parts fixed.'=>'✓ Partes arregladas.','✓ Pattern translated.'=>'✓ Patrón traducido.','✓ Refined — review the updated draft above.'=>'✓ Refinado — revisa el borrador actualizado arriba.','✓ Translation saved'=>'✓ Traducción guardada','✗ Disabled'=>'✗ Desactivado','✗ Error:'=>'✗ Error:','✗ Failed:'=>'✗ Fallido:','✗ Not configured'=>'No configurado ✗','✗ Too long'=>'✗ Demasiado largo','✗ Too short'=>'✗ Demasiado corto','❌ Failed'=>'❌ Fallido','📄 Wrong template'=>'📄 Plantilla incorrecta','📍 Stale path (page moved)'=>'📍 Ruta obsoleta (página movida)']];
